// HYPOTHETICAL RESEARCH ONLY. Runs the scoring-frame Option A simulation for MK's methodology decisions and writes
// the results to docs/readiness-review/methodology-simulation/. Fictional records only; nothing is stored, delivered
// or connected to any product. Every value produced is labelled hypothetical.
// node --experimental-strip-types --experimental-loader=./scripts/lib/ts-relative-resolve-loader.mjs scripts/research/scoring-simulation/run.mjs
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { BANK, COVERAGE, DOMAINS, EXTENDED_CEILING, HYPOTHETICAL, POLICIES, PRODUCTION_CEILING, PROFILES, QI, ROOT, SCENARIOS, draw, interview, practiceValue, withUnknown } from './lib.mjs';
import { AGGREGATIONS, BANDS, CAP_RULES, CLASS_TREATMENTS, FALSE_COMFORT, FRAMES, FRAME_IDS, VISIBILITY_RULES, WEIGHTINGS, bandOf, simulate } from './calculator.mjs';
import { buildMembership, membershipCsv, membershipSummary } from './membership.mjs';
import { FIXTURE_NOTES, loadFixtures } from './fixtures.mjs';

const OUT = path.join(ROOT, 'docs/readiness-review/methodology-simulation');
// The configuration recommended in METHODOLOGY-DECISION-PACKAGE.md (still hypothetical).
const RECOMMENDED = { frame: 'A1', treatment: 'interval', aggregation: 'pooled', weighting: 'equal', falseComfort: 'F2F4', caps: 'K1-K3', visibility: 'recommended', bandBasis: 'lower' };
mkdirSync(OUT, { recursive: true });
const ROLE = COVERAGE.questionRole;
const results = { label: HYPOTHETICAL, bank: BANK.bankVersion, engine: 'review-engine-build-1.5', generatedFor: 'MK methodology decision package' };
const md = [];
const h = (level, text) => md.push(`\n${'#'.repeat(level)} ${text}\n`);
const p = (text) => md.push(`${text}\n`);
const table = (head, rows) => { md.push(`| ${head.join(' | ')} |`); md.push(`|${head.map(() => '---').join('|')}|`); for (const r of rows) md.push(`| ${r.map((c) => (c === null || c === undefined ? '' : String(c))).join(' | ')} |`); md.push(''); };
const fmt = (x) => (x === null || x === undefined ? 'withheld' : Number.isInteger(x) ? String(x) : x.toFixed(1));
const range = (o) => (o.lo === null ? 'n/a' : o.lo === o.hi ? fmt(o.lo) : `${fmt(o.lo)} to ${fmt(o.hi)}`);
const shown = (s) => (s.overall.withheld ? `withheld (${range(s.overall)})` : `${fmt(s.overall.point)} (${range(s.overall)})`);
const band = (s) => (s.band.final ? `${s.band.final}${s.band.capLowered ? ` (calculated ${s.band.calculated}; ${s.band.caps.join(', ')})` : ''}${s.band.indeterminate ? ' [range spans two bands]' : ''}` : 'withheld');
const brief = (s) => ({ population: s.population, metrics: s.metrics, overall: s.overall, band: s.band, visibility: s.visibility, classProfile: s.classProfile, inPlaceSharePct: s.inPlaceSharePct, scenarioPicture: s.scenarioPicture, contradictions: s.contradictions, domains: s.domains });

p(`# Scoring simulation results (generated)\n\n> ${HYPOTHETICAL}. Generated by \`scripts/research/scoring-simulation/run.mjs\` from bank ${BANK.bankVersion}, coverage map 1.3 and review engine build 1.5, on fictional records only. Every treatment, weight, threshold, cap and band here is a hypothesis for MK's decision and is excluded from production. Read with \`METHODOLOGY-DECISION-PACKAGE.md\`.`);
h(2, 'Hypotheses used');
table(['Parameter', 'Options simulated'], [
  ['Frame', Object.entries(FRAMES).map(([k, v]) => `${k}: ${v.note}`).join('<br>')],
  ['Class treatment (non-anchored answers)', Object.entries(CLASS_TREATMENTS).map(([k, v]) => `${k}: ${v.note}${v.values ? ` (${Object.entries(v.values).map(([c, r]) => `${c} ${r[0] === r[1] ? r[0] : r.join('-')}`).join(', ')})` : ''}`).join('<br>')],
  ['Weighting', Object.entries(WEIGHTINGS).map(([k, v]) => `${k}: ${v.note}`).join('<br>')],
  ['Aggregation', Object.entries(AGGREGATIONS).map(([k, v]) => `${k}: ${v}`).join('<br>')],
  ['False comfort', Object.entries(FALSE_COMFORT).map(([k, v]) => `${k}: ${v}`).join('<br>')],
  ['Visibility', Object.entries(VISIBILITY_RULES).map(([k, v]) => `${k}: ${v.note}`).join('<br>')],
  ['Bands (comparator)', BANDS.map(([m, b]) => `${b} from ${m}`).join(', ')],
  ['Caps (comparator structure)', Object.entries(CAP_RULES).map(([k, v]) => `${k}: ${v}`).join('<br>')]
]);
p('Defaults unless stated: frame A, interval treatment, equal weighting, equal domains, F0, proposed visibility, caps on. Anchored answers are always level x 20, the existing normalisation.');

// ================================================================================================ 1. membership
const { rows: mrows } = buildMembership();
const msum = membershipSummary(mrows);
// Reachability: which questions the respondent interview actually serves, across fictional profiles and answer patterns.
const served = new Map();
let reachRuns = 0;
for (const prof of Object.keys(PROFILES)) for (const pol of ['strong', 'weak', 'mixed', 'uniform']) for (const seed of ['r1', 'r2', 'r3']) for (const assumptions of ['none', 'all']) {
  const e = interview({ profile: prof, policy: withUnknown(POLICIES[pol], 0.1, `u-${seed}`), seed, ceiling: EXTENDED_CEILING, assumptions });
  reachRuns++;
  for (const x of e.S.log) if (x.via === 'respondent' && QI.has(x.q)) { if (!served.has(x.q)) served.set(x.q, new Set()); served.get(x.q).add(x.kind); }
}
writeFileSync(path.join(OUT, 'membership-matrix.csv'), membershipCsv(mrows, served));
const reach = { runs: reachRuns, byRole: {} };
for (const r of mrows) {
  const k = `${r.type}/${r.coverageRole}`;
  reach.byRole[k] ??= { total: 0, served: 0, servedAs: {} };
  reach.byRole[k].total++;
  if (served.has(r.id)) { reach.byRole[k].served++; for (const kind of served.get(r.id)) reach.byRole[k].servedAs[kind] = (reach.byRole[k].servedAs[kind] || 0) + 1; }
}
results.membership = { summary: msum, reachability: reach };
writeFileSync(path.join(OUT, 'membership-summary.json'), `${JSON.stringify(results.membership, null, 1)}\n`);

h(2, '1. Scoring-frame membership');
p(`All ${msum.live} live questions (912 with ${912 - msum.live} retired) are listed one per row in \`membership-matrix.csv\` with their type, format, stage, coverage-map role, every scenario association (as confirmation, follow-up or related), tiers, objectives, cross-objectives, the frame flag, every gating condition and whether the simulated interviews ever served them.`);
table(['Type / role', 'Questions', 'In the Option A frame', 'Served in simulated respondent interviews', 'Served as'], Object.entries(reach.byRole).sort((a, b) => b[1].total - a[1].total).map(([k, v]) => [k, v.total, k === 'practice/confirm' ? v.total : 0, `${v.served} of ${v.total}`, Object.entries(v.servedAs).map(([a, n]) => `${a} ${n}`).join(', ')]));
p(`Reachability is from ${reachRuns} simulated interviews (six fictional profiles, four answer patterns with 10% unknowns, three seeds, the activities screen answered both ways, extended screen limit).`);
table(['Check', 'Result'], [
  ['Frame candidates (practice questions with the confirmation role)', msum.frame],
  ['Anchored / non-anchored', `${msum.frameAnchored} / ${msum.frameNonAnchored} (practice ${msum.frameByFormat.practice}, choice ${msum.frameByFormat.choicePractice})`],
  ['Core / detail stage', `${msum.frameByStage.core} / ${msum.frameByStage.detail}`],
  ['Confirmations naming more than one scenario', msum.frameMultiScenario.length],
  ['Each confirmation\'s role scenario equals its only route or confirm scenario', msum.roleScenarioMatchesConfirmation ? 'yes, all 137' : 'no'],
  ['Confirmations also listed as a follow-up or related question of another scenario', msum.frameAlsoFollowupOrRelated.map((x) => `${x.id} (${[...x.followupOf.map((s) => `follow-up of ${s}`), ...x.relatedOf.map((s) => `related to ${s}`)].join(', ')})`).join('; ')],
  ['Scenarios with more than one confirmation (alternative or joint routes)', msum.scenariosWithSeveralConfirmations],
  ['Scenarios without a confirmation', msum.scenariosWithoutConfirmation.length],
  ['Questions with any scenario association / with several', `${msum.questionsWithAnyScenarioAssociation} / ${msum.questionsWithSeveralScenarioAssociations}`],
  ['Follow-ups listed for two scenarios', msum.followUpListedForSeveralScenarios],
  ['Related questions listed for several scenarios', msum.relatedListedForSeveralScenarios],
  ['Scenarios with follow-ups / without', `${msum.scenariosWithFollowUps} / ${msum.scenarioCount - msum.scenariosWithFollowUps}`],
  ['Confirmation-role questions that are not practices', msum.confirmRoleNotPractice.length]
]);
h(3, '1.1 The 137 confirmations by domain, format and tier');
table(['Domain', 'Name', 'Anchored', 'Non-anchored', 'Tier 1', 'Tier 2', 'Tier 3', 'Tier 1 anchored', 'Tier 1 non-anchored'], DOMAINS.map((d) => [d.id, d.name, msum.frameByDomain[d.id].anchored, msum.frameByDomain[d.id].nonAnchored, ...msum.frameByDomainAndTier[d.id], msum.frameTier1ByDomainAndFormat[d.id].anchored, msum.frameTier1ByDomainAndFormat[d.id].nonAnchored]));
table(['Tier', 'Anchored', 'Practice', 'Choice', 'Non-anchored share'], msum.frameFormatByTier.map((t) => [t.tier, t.anchored, t.practice, t.choicePractice, `${Math.round(((t.practice + t.choicePractice) / (t.anchored + t.practice + t.choicePractice)) * 100)}%`]));
h(3, '1.2 What decides whether a confirmation applies (static)');
table(['Gating', 'Confirmations'], Object.entries(msum.frameGateKinds).sort((a, b) => b[1] - a[1]));

// ================================================================================================ 2. applicability by profile
h(2, '2. Applicability of the 137 confirmations across fictional profiles');
p('Every practice answered strongly so the interview runs to its own end (extended screen limit); the activities screen answered "none" and, separately, every assumed activity selected. Counts are confirmations.');
const appRows = [];
results.applicability = {};
for (const prof of Object.keys(PROFILES)) for (const assumptions of ['none', 'all']) {
  const e = interview({ profile: prof, policy: POLICIES.strong, ceiling: EXTENDED_CEILING, assumptions });
  const s = simulate(e.report());
  const app = s.controls.filter((c) => ['known', 'unknown', 'notReached'].includes(c.category));
  const t1app = app.filter((c) => c.tier === 1).length;
  results.applicability[`${prof}/${assumptions}`] = { population: s.population, byDomain: s.domains.map((d) => ({ id: d.id, applicable: d.applicable, excluded: d.excluded })), anchoredApplicable: app.filter((c) => c.format === 'anchored').length, tier1Applicable: t1app, screens: e.respondentScreens() };
  appRows.push([PROFILES[prof].label, assumptions, e.respondentScreens(), s.population.applicable, `${app.filter((c) => c.format === 'anchored').length} / ${app.filter((c) => c.format !== 'anchored').length}`, t1app, s.population.excluded, Object.entries(s.population.excludedByState).map(([k, v]) => `${k} ${v}`).join(', '), s.population.pendingApplicability, s.domains.map((d) => d.applicable).join(' / ')]);
}
table(['Profile', 'Activities screen', 'Screens to finish', 'Applicable', 'Anchored / non-anchored applicable', 'Tier 1 applicable', 'Excluded', 'Excluded as', 'Applicability not known', 'Applicable by domain D1 to D10'], appRows);
const ap = Object.values(results.applicability).map((a) => a.population.applicable);
p(`Applicable confirmations range from ${Math.min(...ap)} to ${Math.max(...ap)} of 137 across these profiles.`);

// ================================================================================================ representative profiles
function contradictionInterview({ profile, ceiling, seed = 'mk-sim' }) {
  // Confirmations whose scenario has follow-ups are first reported partly in place, so the interview asks the follow-ups;
  // the follow-ups are reported weak; the respondent then corrects every confirmation to in place.
  const kindPolicy = (q, st, sd) => {
    const role = ROLE[q.id];
    if (role?.role === 'confirm' && (SCENARIOS.get(role.scenario).followups || []).length) return q.format === 'anchored' ? 3 : 'partial';
    if (st.kind === 'followup') return draw(`${sd}|fu`, q.id) < 0.5 ? (q.format === 'anchored' ? 0 : 'absent') : q.format === 'anchored' ? 2 : 'partial';
    return null;
  };
  const e = interview({ profile, policy: POLICIES.strong, ceiling, seed, kindPolicy });
  let corrected = 0;
  for (const id of FRAME_IDS) { const a = e.S.ans[id]; if (a && !a.stale && ['partial', 'designed', 'absent'].includes(a.cls)) { e.correct(id, practiceValue(e.QI[id], POLICIES.strong(QI.get(id), seed))); corrected++; } }
  e.corrected = corrected;
  // A correction can open questions that depended on the corrected answer; the interview continues with in-place answers.
  interview({ profile, policy: POLICIES.strong, ceiling, seed, engine: e });
  return e;
}
const PROFILE_DEFS = {
  P1: { name: 'Strong controls', profile: 'R', run: (c) => interview({ profile: 'R', policy: POLICIES.strong, ceiling: c }) },
  P2: { name: 'Weak controls', profile: 'R', run: (c) => interview({ profile: 'R', policy: POLICIES.weak, ceiling: c }) },
  P3: { name: 'Mixed controls (governance, risk, ethics, finance and detection strong; third parties, people, customers, assets and digital weak)', profile: 'R', run: (c) => interview({ profile: 'R', policy: POLICIES.mixed, ceiling: c }) },
  P4: { name: 'Limited applicability (small owner-managed firm, mixed answers)', profile: 'S', run: (c) => interview({ profile: 'S', policy: POLICIES.mixed, ceiling: c }) },
  P5: { name: 'Extensive unanswered information (mixed answers, 35% "I don\'t know")', profile: 'R', run: (c) => interview({ profile: 'R', policy: withUnknown(POLICIES.mixed, 0.35), ceiling: c }) },
  P6: { name: 'Confirmations contradicting follow-ups (confirmations corrected to in place after weak follow-ups)', profile: 'R', run: (c) => contradictionInterview({ profile: 'R', ceiling: c }) }
};
const RUNS = {};
for (const [k, def] of Object.entries(PROFILE_DEFS)) for (const c of [PRODUCTION_CEILING, EXTENDED_CEILING]) RUNS[`${k}@${c}`] = def.run(c);
const FIX = await loadFixtures();

// ================================================================================================ 3. non-anchored treatments
h(2, '3. Numerical treatment of non-anchored confirmations');
p('The same records under each class treatment. Anchored confirmations are identical in every column; only the 40 non-anchored confirmations (6 of them tier 1) are treated differently. Overall: equal domains.');
const tRows = [];
results.treatments = {};
const treatmentCases = [['P1 strong', RUNS[`P1@${EXTENDED_CEILING}`]], ['P2 weak', RUNS[`P2@${EXTENDED_CEILING}`]], ['P3 mixed', RUNS[`P3@${EXTENDED_CEILING}`]], ['Uniform answers', interview({ profile: 'R', policy: POLICIES.uniform, ceiling: EXTENDED_CEILING })], ['P4 limited applicability', RUNS[`P4@${EXTENDED_CEILING}`]], ['Supplied fixture', FIX.supplied.engine]];
for (const frame of ['A', 'A1']) for (const [name, e] of treatmentCases) {
  const rep = e.report();
  const row = [frame, name];
  const per = {};
  for (const t of Object.keys(CLASS_TREATMENTS)) { const s = simulate(rep, { frame, treatment: t }); per[t] = s; row.push(t === 'exclude' ? `${fmt(s.overall.point)} [${s.population.knownScored} of ${s.population.known} scored]` : `${t === 'interval' ? range(s.overall) : fmt(s.overall.point)} ${s.band.calculated ? `(${s.band.calculated}${t === 'interval' && s.band.indeterminate ? '/' + s.band.hi : ''})` : ''}`); }
  const s0 = per.interval;
  const nonAnch = s0.controls.filter((c) => c.category === 'known' && c.format !== 'anchored').length;
  row.splice(2, 0, `${nonAnch} of ${s0.population.known}`);
  const pts = ['lower', 'midpoint', 'labelEquivalent'].map((t) => per[t].overall.point).filter((x) => x !== null);
  row.push(pts.length ? fmt(Math.max(...pts) - Math.min(...pts)) : 'n/a');
  tRows.push(row);
  results.treatments[`${frame}/${name}`] = Object.fromEntries(Object.entries(per).map(([t, s]) => [t, { overall: s.overall, band: s.band.calculated, knownScored: s.population.knownScored, known: s.population.known }]));
}
table(['Frame', 'Record', 'Non-anchored known', 'exclude', 'interval', 'lower', 'midpoint', 'labelEquivalent', 'Spread lower to labelEquivalent'], tRows);
p('Scores are shown whether or not the visibility rule would withhold them, so the treatments can be compared; band in brackets (interval: lower-end band / upper-end band where they differ).');

// ================================================================================================ 4. impact assessment
h(2, '4. Scoring impact assessment');
const impact = {};
function profileSection(title, note, e, { extra = '' } = {}) {
  const rep = e.report();
  const s = simulate(rep);
  const s1 = simulate(rep, { frame: 'A1' });
  const sm = simulate(rep, { visibility: 'mfrsComparator' });
  impact[title] = { default: brief(s), tier1Frame: brief(s1), mfrsVisibility: { status: sm.visibility.status, reasons: sm.visibility.reasons }, screens: e.respondentScreens(), stopReason: e.S.stopReason };
  h(4, title);
  p(`${note ? `${note} ` : ''}Screens: ${e.respondentScreens()}, interview ${e.S.ended ? `ended (${e.S.stopReason})` : 'in progress'}.${extra}`);
  table(['Measure', 'Frame A (all confirmations)', 'Frame A1 (tier 1 confirmations)'], [
    ['Confirmations in the frame', s.population.frameTotal, s1.population.frameTotal],
    ['Applicable (known + unknown + not reached)', s.population.applicable, s1.population.applicable],
    ['Known answers (scored)', `${s.population.known} (${s.population.knownScored})`, `${s1.population.known} (${s1.population.knownScored})`],
    ['Unknown, routed to an owner', s.population.unknown, s1.population.unknown],
    ['Not reached by the interview', s.population.notReached, s1.population.notReached],
    ['Applicability not yet known', s.population.pendingApplicability, s1.population.pendingApplicability],
    ['Excluded by scope or proportion', s.population.excluded, s1.population.excluded],
    ['Coverage of applicable (known)', `${fmt(s.metrics.coveragePct)}%`, `${fmt(s1.metrics.coveragePct)}%`],
    ['Unknown share / not reached share', `${fmt(s.metrics.unknownSharePct)}% / ${fmt(s.metrics.notReachedSharePct)}%`, `${fmt(s1.metrics.unknownSharePct)}% / ${fmt(s1.metrics.notReachedSharePct)}%`],
    ['Tier 1 coverage', `${fmt(s.metrics.tier1CoveragePct)}%`, `${fmt(s1.metrics.tier1CoveragePct)}%`],
    ['Overall (equal domains; interval)', shown(s), shown(s1)],
    ['Band (existing thresholds and transposed caps)', band(s), band(s1)],
    ['Visibility (proposed rules)', s.visibility.status, s1.visibility.status],
    ['Visibility reasons', s.visibility.reasons.join('; ') || 'none', s1.visibility.reasons.join('; ') || 'none'],
    ['Visibility under the MFRS rules on the frame', sm.visibility.status, ''],
    ['Class profile of known confirmations (full / partial / designed / absent)', Object.values(s.classProfile).join(' / '), Object.values(s1.classProfile).join(' / ')],
    ['In-place share of known confirmations', `${fmt(s.inPlaceSharePct)}%`, `${fmt(s1.inPlaceSharePct)}%`],
    ['Contradictions (in place with follow-up gap / gap with follow-ups in place)', `${s.contradictions.filter((c) => c.kind.startsWith('in-place')).length} / ${s.contradictions.filter((c) => c.kind.startsWith('gap')).length}`, `${s1.contradictions.filter((c) => c.kind.startsWith('in-place')).length} / ${s1.contradictions.filter((c) => c.kind.startsWith('gap')).length}`]
  ]);
  table(['Domain', 'Applicable', 'Known', 'Unknown', 'Not reached', 'Pending', 'Excluded', 'Coverage', 'Result (interval)', 'Shown'], s.domains.map((d) => [d.id, d.applicable, d.known, d.unknown, d.notReached, d.pending, d.excluded, d.coveragePct === null ? 'n/a' : `${fmt(d.coveragePct)}%`, d.lo === null ? 'n/a' : range(d), d.visible ? 'yes' : 'no']));
  const sp = s.scenarioPicture;
  p(`Scenario picture (engine statuses, ${sp.applicableOrPossible} scenarios applicable or not yet settled, ${sp.outOfScope} out of scope): ${Object.entries(sp.byStatus).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ')}. Tier 1: ${Object.entries(sp.tier1).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ')}.`);
  return s;
}
h(3, '4.1 Existing fictional fixtures');
p('The supplied 1.2.0 session and the seven golden sessions, each matching its pinned log digest. Frame A, defaults.');
const fixRows = [];
results.fixtures = {};
for (const [name, f] of Object.entries(FIX)) {
  const rep = f.engine.report();
  const s = simulate(rep), s1 = simulate(rep, { frame: 'A1' });
  results.fixtures[name] = { note: FIXTURE_NOTES[name], actions: f.actions, logDigest: f.logDigest, default: brief(s), tier1Frame: brief(s1) };
  fixRows.push([name, FIXTURE_NOTES[name], f.engine.respondentScreens(), `${s.population.known} / ${s.population.applicable}`, s.population.unknown, s.population.notReached, s.population.pendingApplicability, `${fmt(s.metrics.coveragePct)}% (t1 ${fmt(s.metrics.tier1CoveragePct)}%)`, `${s.visibility.status}: ${shown(s)}`, band(s), `${s1.visibility.status}: ${shown(s1)}`, `${s.contradictions.filter((c) => c.kind.startsWith('in-place')).length} / ${s.contradictions.filter((c) => c.kind.startsWith('gap')).length}`]);
}
table(['Fixture', 'What it is', 'Screens', 'Known / applicable', 'Unknown', 'Not reached', 'Applicability not known', 'Coverage', 'Frame A result', 'Frame A band', 'Frame A1 result', 'Contradictions (false comfort / understatement)'], fixRows);
h(3, '4.2 Representative profiles');
p('Base organisation: the Fictional Retail Group profile of the golden sessions (P4 uses the small owner-managed firm). Each profile is run through the production screen limit (95) and, for comparison, through the interview\'s own end (extended limit, research only). Answers are fixed per question, so both runs describe the same organisation.');
results.impact = impact;
for (const [k, def] of Object.entries(PROFILE_DEFS)) for (const c of [PRODUCTION_CEILING, EXTENDED_CEILING]) profileSection(`${k} ${def.name}, ${c === PRODUCTION_CEILING ? 'production screen limit (95)' : 'interview to its end (extended)'}`, '', RUNS[`${k}@${c}`], { extra: k === 'P6' ? ` Confirmations corrected after the follow-ups: ${RUNS[`${k}@${c}`].corrected}.` : '' });

// ================================================================================================ 5. unknown responses
h(2, '5. Unknown responses (corrected test)');
results.unknown = {};
// U1 denominator.
{
  const e = RUNS[`P5@${EXTENDED_CEILING}`];
  const rep = e.report();
  const s = simulate(rep, { aggregation: 'pooled', treatment: 'midpoint' });
  const known = s.controls.filter((c) => c.value);
  const manual = known.reduce((a, c) => a + c.value.lo, 0) / known.length;
  const unknowns = s.controls.filter((c) => c.category === 'unknown');
  const asZero = (known.reduce((a, c) => a + c.value.lo, 0)) / (known.length + unknowns.length);
  results.unknown.U1 = { known: known.length, unknown: unknowns.length, simulated: s.overall.point, manual: Math.round(manual * 10) / 10, unknownValued: unknowns.filter((c) => c.value).length, unknownAsZeroComparator: Math.round(asZero * 10) / 10 };
  h(3, 'U1 Denominator');
  table(['Check (P5, extended, pooled, midpoint values)', 'Result'], [
    ['Known confirmations scored / unknown confirmations', `${known.length} / ${unknowns.length}`],
    ['Unknown confirmations given any value', unknowns.filter((c) => c.value).length],
    ['Simulated overall vs independent recomputation over known answers only', `${fmt(s.overall.point)} vs ${fmt(Math.round(manual * 10) / 10)}`],
    ['For contrast only (rejected): unknown counted as zero', fmt(Math.round(asZero * 10) / 10)]
  ]);
}
// U2 direction: replace one known answer at a time with an unknown.
{
  const e = RUNS[`P3@${EXTENDED_CEILING}`];
  const rep = e.report();
  const base = simulate(rep), basePooled = simulate(rep, { aggregation: 'pooled' });
  const deltas = [];
  for (const c of base.controls.filter((x) => x.category === 'known')) {
    const s = simulate(rep, { overrides: { [c.id]: 'unknown' } });
    const sp = simulate(rep, { aggregation: 'pooled', overrides: { [c.id]: 'unknown' } });
    deltas.push({ id: c.id, domain: c.domain, tier: c.tier, value: (c.value.lo + c.value.hi) / 2, delta: s.overall.point - base.overall.point, deltaPooled: sp.overall.point - basePooled.overall.point, status: s.visibility.status, domainShown: s.domains.find((d) => d.id === c.domain).visible });
  }
  const up = deltas.filter((d) => d.delta > 0.05), down = deltas.filter((d) => d.delta < -0.05), same = deltas.length - up.length - down.length;
  const upP = deltas.filter((d) => d.deltaPooled > 0.05), downP = deltas.filter((d) => d.deltaPooled < -0.05);
  const ex = (list, f) => list.sort(f)[0];
  const maxUp = ex([...deltas], (a, b) => b.delta - a.delta), maxDown = ex([...deltas], (a, b) => a.delta - b.delta);
  results.unknown.U2 = { base: base.overall.point, basePooled: basePooled.overall.point, n: deltas.length, up: up.length, down: down.length, same, upPooled: upP.length, downPooled: downP.length, maxUp, maxDown, statusAfter: deltas.reduce((a, d) => ((a[d.status] = (a[d.status] || 0) + 1), a), {}) };
  h(3, 'U2 Removing one known answer moves the result either way');
  p(`P3 mixed, extended (base ${fmt(base.overall.point)} equal domains, ${fmt(basePooled.overall.point)} pooled). Each of the ${deltas.length} known confirmations was replaced in turn by "I don't know", with no change to routing.`);
  table(['Aggregation', 'Result rose', 'Result fell', 'Unchanged', 'Largest rise', 'Largest fall'], [
    ['Equal domains', up.length, down.length, same, `+${fmt(maxUp.delta)} (${maxUp.id}, value ${fmt(maxUp.value)})`, `${fmt(maxDown.delta)} (${maxDown.id}, value ${fmt(maxDown.value)})`],
    ['Pooled', upP.length, downP.length, deltas.length - upP.length - downP.length, `+${fmt(Math.max(...deltas.map((d) => d.deltaPooled)))}`, fmt(Math.min(...deltas.map((d) => d.deltaPooled)))]
  ]);
  p(`A known answer below the result raises it when removed; one above lowers it. Removing an answer never assigns a penalty, and the visibility measures always fall (status after one removal: ${Object.entries(results.unknown.U2.statusAfter).map(([k, v]) => `${k} ${v}`).join(', ')}).`);
  // Engine-level: the same unknown given in the interview itself, so routing (follow-ups, screens) also changes.
  const sample = [...deltas].sort((a, b) => a.value - b.value);
  const picks = [...sample.slice(0, 4), ...sample.slice(-4)];
  const eng = [];
  for (const d of picks) {
    const e2 = interview({ profile: 'R', policy: POLICIES.mixed, ceiling: EXTENDED_CEILING, kindPolicy: (q) => (q.id === d.id ? 'unknown' : null) });
    const s2 = simulate(e2.report());
    eng.push([d.id, d.tier, fmt(d.value), `${d.delta >= 0 ? '+' : ''}${fmt(d.delta)}`, `${s2.overall.point - base.overall.point >= 0 ? '+' : ''}${fmt(s2.overall.point - base.overall.point)}`, `${e2.respondentScreens()} (base ${e.respondentScreens()})`, s2.visibility.status]);
  }
  results.unknown.U2engine = eng;
  table(['Confirmation answered "I don\'t know" in the interview', 'Tier', 'Its known value', 'Change, answer removed only', 'Change, interview rerun', 'Screens', 'Visibility'], eng);
}
// U3 visibility ladder.
{
  const complete = simulate(RUNS[`P3@${EXTENDED_CEILING}`].report());
  const ladder = [];
  for (const rate of [0, 0.05, 0.1, 0.15, 0.2, 0.25, 0.3, 0.4, 0.5]) {
    const res = [];
    for (let k = 0; k < 10; k++) {
      const e = interview({ profile: 'R', policy: withUnknown(POLICIES.mixed, rate, `ladder-${k}`), ceiling: EXTENDED_CEILING });
      const s = simulate(e.report());
      const r95 = interview({ profile: 'R', policy: withUnknown(POLICIES.mixed, rate, `ladder-${k}`), ceiling: PRODUCTION_CEILING }).report();
      res.push({ s, s95: simulate(r95), s95a1: simulate(r95, { frame: 'A1' }) });
    }
    const pts = res.map((r) => r.s.overall.point);
    const st = res.reduce((a, r) => ((a[r.s.visibility.status] = (a[r.s.visibility.status] || 0) + 1), a), {});
    const st95 = res.reduce((a, r) => ((a[r.s95.visibility.status] = (a[r.s95.visibility.status] || 0) + 1), a), {});
    const st95a1 = res.reduce((a, r) => ((a[r.s95a1.visibility.status] = (a[r.s95a1.visibility.status] || 0) + 1), a), {});
    const pts1 = res.map((r) => r.s95a1.overall.point).filter((x) => x !== null);
    ladder.push({ rate, unknownShare: res.reduce((a, r) => a + r.s.metrics.unknownSharePct, 0) / res.length, status: st, status95: st95, status95a1: st95a1, a1min: Math.min(...pts1), a1max: Math.max(...pts1), min: Math.min(...pts), max: Math.max(...pts), up: pts.filter((x) => x > complete.overall.point + 0.05).length, down: pts.filter((x) => x < complete.overall.point - 0.05).length, domainsHidden: res.reduce((a, r) => a + r.s.domains.filter((d) => d.applicable && !d.visible).length, 0) / res.length });
  }
  results.unknown.U3 = { complete: complete.overall.point, ladder };
  h(3, 'U3 Visibility, withholding and disclosure as unknowns increase');
  p(`P3 mixed answers with a share of answers replaced at random by "I don't know" (ten seeds per rate). Complete result: ${fmt(complete.overall.point)}. Calculated results are shown even where they would be withheld.`);
  const cnt = (o) => Object.entries(o).map(([k, v]) => `${k} ${v}`).join(', ');
  table(['Unknown rate', 'Mean unknown share of applicable', 'Frame A, extended (of 10)', 'Frame A, production limit', 'Frame A1, production limit', 'Frame A extended: calculated range', 'Above / below the complete result', 'Frame A1 production: calculated range', 'Domains withheld (mean, frame A extended)'], ladder.map((l) => [`${Math.round(l.rate * 100)}%`, `${fmt(l.unknownShare)}%`, cnt(l.status), cnt(l.status95), cnt(l.status95a1), `${fmt(l.min)} to ${fmt(l.max)}`, `${l.up} / ${l.down}`, `${fmt(l.a1min)} to ${fmt(l.a1max)}`, fmt(l.domainsHidden)]));
}
// U4 disclosure.
{
  const e = RUNS[`P5@${PRODUCTION_CEILING}`];
  const s = simulate(e.report());
  const unknowns = s.controls.filter((c) => c.category === 'unknown');
  const byOwner = {};
  for (const c of unknowns) { const o = QI.get(c.id).owner || 'Not named'; byOwner[o] ??= { total: 0, tier1: 0, fn: e.functionOf(o) }; byOwner[o].total++; if (c.tier === 1) byOwner[o].tier1++; }
  results.unknown.U4 = { unknown: unknowns.length, listed: Object.values(byOwner).reduce((a, x) => a + x.total, 0), byOwner };
  h(3, 'U4 Disclosure of outstanding information');
  p(`P5 at the production limit: ${unknowns.length} applicable confirmations answered "I don't know", each listed once under the accountable function the bank names for its module (${results.unknown.U4.listed} listed). Visibility ${s.visibility.status}; result ${shown(s)}.`);
  table(['Suggested owner (bank module)', 'Engine function package', 'Outstanding confirmations', 'Of which tier 1'], Object.entries(byOwner).sort((a, b) => a[1].fn.localeCompare(b[1].fn)).map(([k, v]) => [k, v.fn, v.total, v.tier1]));
}
// U5 strategic non-disclosure: the lowest answers turned into unknowns one by one.
{
  const e = RUNS[`P2@${EXTENDED_CEILING}`];
  const rep = e.report();
  const base = simulate(rep);
  const order = base.controls.filter((c) => c.category === 'known').sort((a, b) => a.value.lo + a.value.hi - (b.value.lo + b.value.hi));
  const steps = [];
  for (let k = 0; k <= order.length; k++) {
    const ov = Object.fromEntries(order.slice(0, k).map((c) => [c.id, 'unknown']));
    const s = simulate(rep, { overrides: ov });
    const s1 = simulate(rep, { frame: 'A1', overrides: ov });
    steps.push({ k, point: s.overall.point, status: s.visibility.status, shown: s.overall.shown, band: s.band.final, unknownShare: s.metrics.unknownSharePct, t1: s1.visibility.status, t1point: s1.overall.point, t1shown: s1.overall.shown });
  }
  const lastOf = (st) => [...steps].reverse().find((x) => x.status === st);
  const firstOf = (st) => steps.find((x) => x.status === st);
  results.unknown.U5 = { base: base.overall.point, steps: steps.filter((x, i) => i % 3 === 0 || x.status !== steps[Math.max(0, i - 1)].status) };
  h(3, 'U5 Strategic use of "I don\'t know"');
  p(`P2 weak, extended: the respondent's lowest known confirmations are replaced one at a time by "I don't know" (worst first). Base ${fmt(base.overall.point)} (${base.visibility.status}).`);
  table(['Answers withheld', 'Unknown share (frame A)', 'Frame A calculated', 'Frame A visibility', 'Frame A shown', 'Frame A1 calculated', 'Frame A1 visibility', 'Frame A1 shown'], steps.filter((x, i) => i <= 40 && (i % 2 === 0 || x.status !== steps[Math.max(0, i - 1)].status || x.t1 !== steps[Math.max(0, i - 1)].t1)).map((x) => [x.k, `${fmt(x.unknownShare)}%`, fmt(x.point), x.status, x.shown === null ? 'withheld' : fmt(x.shown), fmt(x.t1point), x.t1, x.t1shown === null ? 'withheld' : fmt(x.t1shown)]));
  const lastNormal = lastOf('NORMAL'), lastProv = lastOf('PROVISIONAL');
  p(`The last result shown as NORMAL is after ${lastNormal ? lastNormal.k : 0} answers withheld (${lastNormal ? fmt(lastNormal.point) : 'n/a'}); the last shown at all is after ${lastProv ? lastProv.k : 'none'} (${lastProv ? fmt(lastProv.point) : 'n/a'}, PROVISIONAL); from ${firstOf('INSUFFICIENT') ? firstOf('INSUFFICIENT').k : 'n/a'} the result is withheld.`);
  const lastShownA1 = [...steps].reverse().find((x) => x.t1shown !== null);
  p(`Frame A1: the last result shown is after ${lastShownA1.k} answers withheld (${fmt(lastShownA1.t1point)}, ${lastShownA1.t1}), against ${fmt(steps[0].t1point)} with every answer given.`);
  results.unknown.U5.summary = { lastNormal, lastProvisional: lastProv, firstInsufficient: firstOf('INSUFFICIENT'), lastShownA1 };
}

// ================================================================================================ 6. false comfort
h(2, '6. False comfort');
const fcRows = [];
const incidence = [];
for (const [name, f] of Object.entries(FIX)) { const s = simulate(f.engine.report()); incidence.push([`fixture ${name}`, s.contradictions.filter((c) => c.kind.startsWith('in-place')).length, s.contradictions.filter((c) => c.kind.startsWith('gap')).length, s.contradictions.filter((c) => c.kind.startsWith('in-place')).map((c) => `${c.confirmation} (${c.scenario}, tier ${c.tier})`).join(', ')]); }
for (const [k, e] of Object.entries(RUNS)) { const s = simulate(e.report()); incidence.push([k, s.contradictions.filter((c) => c.kind.startsWith('in-place')).length, s.contradictions.filter((c) => c.kind.startsWith('gap')).length, s.contradictions.filter((c) => c.kind.startsWith('in-place')).slice(0, 6).map((c) => `${c.confirmation} (${c.scenario}, tier ${c.tier})`).join(', ') + (s.contradictions.filter((c) => c.kind.startsWith('in-place')).length > 6 ? ', ...' : '')]); }
results.falseComfort = { incidence };
h(3, '6.1 How often the responses themselves contradict a confirmation');
table(['Record', 'In place, follow-up gap', 'Gap, follow-ups in place', 'In-place confirmations contradicted'], incidence);
// Structural reach: follow-ups are asked only after a gap is reported.
{
  const e = RUNS[`P1@${EXTENDED_CEILING}`];
  const rep = e.report();
  const s = simulate(rep);
  const known = s.controls.filter((c) => c.category === 'known');
  const inPlace = known.filter((c) => c.cls === 'full');
  const withFu = inPlace.filter((c) => (SCENARIOS.get(c.scenario).followups || []).length);
  const fuAsked = withFu.filter((c) => (SCENARIOS.get(c.scenario).followups || []).some((f) => e.S.ans[f]));
  const t1withFu = COVERAGE.scenarios.filter((x) => x.tier === 1 && (x.followups || []).length).length;
  results.falseComfort.reach = { inPlace: inPlace.length, withFollowUps: withFu.length, followUpsAsked: fuAsked.length, tier1ScenariosWithFollowUps: t1withFu };
  h(3, '6.2 Where the interview can and cannot reveal a contradiction');
  p(`The engine asks a scenario's follow-ups only after one of its confirmations is reported as a gap (build 1.5, up to two per scenario). In P1 (strong, extended), ${inPlace.length} confirmations are reported fully in place; ${withFu.length} belong to scenarios that have follow-ups; the follow-ups were asked for ${fuAsked.length} of them. A contradiction can therefore surface only where the routing asks the follow-up anyway: a scenario with two confirmations where the other reported a gap (14 scenarios), a follow-up shared with another scenario (D1-A-09, D6-P-03), a confirmation corrected after its follow-ups were answered, or an owner's answer. An organisation that reports every confirmation in place is not asked a follow-up, so nothing in its own responses can contradict it. ${t1withFu} of the 55 tier 1 scenarios have follow-ups.`);
}
// Treatments F0 to F4 on the contradiction profile and the fixtures with contradictions.
{
  h(3, '6.3 Alternative treatments');
  const cases = [['P6, production limit', RUNS[`P6@${PRODUCTION_CEILING}`]], ['P6, production limit, frame A1', RUNS[`P6@${PRODUCTION_CEILING}`], 'A1'], ['P6, extended', RUNS[`P6@${EXTENDED_CEILING}`]], ['P6, extended, frame A1', RUNS[`P6@${EXTENDED_CEILING}`], 'A1'], ['Supplied fixture', FIX.supplied.engine], ['Golden fullInterview', FIX.fullInterview.engine], ['P1 strong, extended', RUNS[`P1@${EXTENDED_CEILING}`]]];
  const rows = [];
  results.falseComfort.treatments = {};
  for (const [name, e, frame = 'A'] of cases) {
    const rep = e.report();
    for (const fc of Object.keys(FALSE_COMFORT)) {
      const s = simulate(rep, { falseComfort: fc, frame });
      const sl = simulate(rep, { falseComfort: fc, treatment: 'labelEquivalent', frame });
      results.falseComfort.treatments[`${name}/${fc}`] = { overall: s.overall, band: s.band, visibility: s.visibility.status };
      rows.push([name, fc, s.contradictions.filter((c) => c.kind.startsWith('in-place')).length, `${s.overall.point === null ? 'n/a' : fmt(s.overall.point)} (${range(s.overall)})`, s.overall.withheld ? 'withheld' : 'shown', s.band.calculated ? band(s) : 'n/a', s.visibility.status, fmt(sl.overall.point)]);
    }
  }
  table(['Record', 'Treatment', 'Contradicted confirmations', 'Calculated result (interval)', 'Shown', 'Band', 'Visibility', 'Result with labelEquivalent values'], rows);
  const p6 = simulate(RUNS[`P6@${EXTENDED_CEILING}`].report());
  const fuGaps = p6.contradictions.filter((c) => c.kind.startsWith('in-place'));
  p(`P6 extended under F0: ${shown(p6)}, ${band(p6)}, ${p6.visibility.status}, while ${fuGaps.length} of its in-place confirmations have a follow-up the respondent reports as a gap (${fuGaps.filter((c) => c.severity === 'follow-up not in place').length} of them with a follow-up not in place at all).`);
}

// ================================================================================================ 7. comparability
h(2, '7. Comparability');
results.comparability = {};
{
  h(3, '7.1 The same answers in different organisations');
  p('Every organisation gives the same answer to every question it is asked (mixed pattern, keyed by question); only the profile differs, so any difference in the result comes from which confirmations apply.');
  const rows = [];
  for (const prof of Object.keys(PROFILES)) {
    const e = interview({ profile: prof, policy: POLICIES.mixed, ceiling: EXTENDED_CEILING });
    const s = simulate(e.report()), sp = simulate(e.report(), { aggregation: 'pooled' }), s1 = simulate(e.report(), { frame: 'A1' }), sr = simulate(e.report(), RECOMMENDED);
    results.comparability[`profile ${prof}`] = { applicable: s.population.applicable, overall: s.overall, pooled: sp.overall, tier1: s1.overall, band: s.band.final, recommended: { applicable: sr.population.applicable, overall: sr.overall, band: sr.band.final, caps: sr.band.caps } };
    rows.push([PROFILES[prof].label, s.population.applicable, s.domains.map((d) => d.applicable).join('/'), shown(s), fmt(sp.overall.point), shown(s1), band(s), `${sr.population.applicable}: ${fmt(sr.overall.point)} ${sr.band.final}${sr.band.capLowered ? ` (${sr.band.caps.join(', ')})` : ''}`]);
  }
  table(['Organisation', 'Applicable', 'By domain', 'Equal domains', 'Pooled', 'Frame A1', 'Band', 'Recommended configuration (tier 1 applicable: result, band)'], rows);
}
{
  h(3, '7.2 The same organisation on different assessment paths');
  const rows = [];
  const add = (label, e) => { const s = simulate(e.report()); const s1 = simulate(e.report(), { frame: 'A1' }); rows.push([label, e.respondentScreens(), `${s.population.known} / ${s.population.applicable}`, `${fmt(s.metrics.coveragePct)}%`, `${s.visibility.status}: ${fmt(s.overall.point)}`, `${s1.visibility.status}: ${fmt(s1.overall.point)}`, band(s)]); results.comparability[`path ${label}`] = { overall: s.overall, status: s.visibility.status, tier1: s1.overall, tier1Status: s1.visibility.status }; };
  for (const [pol, name] of [['strong', 'P1 strong'], ['mixed', 'P3 mixed'], ['weak', 'P2 weak']]) {
    for (const stop of [20, 40, 60]) add(`${name}, respondent stops after ${stop} screens`, interview({ profile: 'R', policy: POLICIES[pol], ceiling: PRODUCTION_CEILING, stopAfter: stop }));
    add(`${name}, production limit (95)`, interview({ profile: 'R', policy: POLICIES[pol], ceiling: PRODUCTION_CEILING }));
    add(`${name}, interview to its end`, interview({ profile: 'R', policy: POLICIES[pol], ceiling: EXTENDED_CEILING }));
  }
  // Owners answer the outstanding confirmations later (a correction recalculation in the existing run types).
  const e = interview({ profile: 'R', policy: withUnknown(POLICIES.mixed, 0.35), ceiling: PRODUCTION_CEILING });
  add('P5, production limit, before owners answer', e);
  let returned = 0;
  for (const id of FRAME_IDS) { const a = e.S.ans[id]; if (a && a.v === 'unknown') { e.ownerReturn(id, practiceValue(e.QI[id], POLICIES.mixed(QI.get(id), 'mk-sim')), { by: 'Fictional owner' }); returned++; } }
  add(`P5, after owners answer ${returned} outstanding confirmations`, e);
  table(['Path', 'Screens', 'Known / applicable', 'Coverage', 'Frame A (calculated, shown or not)', 'Frame A1', 'Band (frame A)'], rows);
}
{
  h(3, '7.3 Method choices that move the same record');
  const rows = [];
  for (const [name, key] of [['P3 mixed, extended', `P3@${EXTENDED_CEILING}`], ['P1 strong, extended', `P1@${EXTENDED_CEILING}`], ['P4 limited, extended', `P4@${EXTENDED_CEILING}`]]) {
    const rep = RUNS[key].report();
    const cell = (o) => { const s = simulate(rep, o); return `${fmt(s.overall.point)} ${s.band.calculated ? `(${s.band.calculated})` : ''}`; };
    rows.push([name, cell({}), cell({ aggregation: 'pooled' }), cell({ weighting: 'tier' }), cell({ weighting: 'tier', aggregation: 'pooled' }), cell({ frame: 'A1' }), cell({ frame: 'A1', aggregation: 'pooled' }), cell({ treatment: 'labelEquivalent' })]);
  }
  table(['Record', 'Equal weight, equal domains', 'Equal weight, pooled', 'Tier weight, equal domains', 'Tier weight, pooled', 'Frame A1, equal domains', 'Frame A1, pooled', 'labelEquivalent values'], rows);
}
{
  h(3, '7.4 A control associated with several scenarios');
  // Synthetic: give one confirmation a second scenario. Option A reads each control once from its own row, so the result
  // cannot change; an aggregation through scenarios would count it twice.
  const rep = RUNS[`P3@${EXTENDED_CEILING}`].report();
  const s = simulate(rep);
  const target = s.controls.find((c) => c.category === 'known' && c.value.hi <= 20) || s.controls.find((c) => c.category === 'known');
  const meanOf = (sid) => { const cs = s.controls.filter((c) => c.value && c.scenario === sid); return cs.length ? cs.reduce((a, c) => a + (c.value.lo + c.value.hi) / 2, 0) / cs.length : null; };
  const other = COVERAGE.scenarios.find((x) => x.id !== target.scenario && rep.scenarios.find((y) => y.id === x.id)?.status !== 'outofscope' && meanOf(x.id) !== null && meanOf(x.id) >= 80);
  const scenarioMean = (extra) => {
    const vals = [];
    for (const sc of rep.scenarios.filter((x) => x.status !== 'outofscope')) {
      const conf = s.controls.filter((c) => c.value && (c.scenario === sc.id || (extra && sc.id === extra.scenario && c.id === extra.id)));
      if (conf.length) vals.push(conf.reduce((a, c) => a + (c.value.lo + c.value.hi) / 2, 0) / conf.length);
    }
    return vals.reduce((a, x) => a + x, 0) / vals.length;
  };
  const a = scenarioMean(null), b = scenarioMean({ id: target.id, scenario: other.id });
  // Effective weight of the target control: Option A pooled gives every scored control 1/n; a scenario aggregation gives it
  // the sum over its scenarios of 1/(scenarios x confirmations in that scenario).
  const scored = s.controls.filter((c) => c.value);
  const scen = rep.scenarios.filter((x) => x.status !== 'outofscope' && scored.some((c) => c.scenario === x.id));
  const nIn = (sid, extra) => scored.filter((c) => c.scenario === sid).length + (extra && extra.scenario === sid ? 1 : 0);
  const wBefore = 1 / (scen.length * nIn(target.scenario));
  const wAfter = wBefore + 1 / (scen.length * nIn(other.id, { scenario: other.id }));
  // The same synthetic association applied to the report itself: the calculator must not change.
  const rep2 = JSON.parse(JSON.stringify(rep));
  rep2.scenarios.find((x) => x.id === other.id).confirmations.push({ id: target.id, state: 'reported', cls: target.cls });
  const s2 = simulate(rep2);
  results.comparability.multiScenario = { target: target.id, value: (target.value.lo + target.value.hi) / 2, secondScenario: other.id, secondScenarioMean: meanOf(other.id), optionA: s.overall.point, optionAAfter: s2.overall.point, pooledWeight: 1 / scored.length, scenarioMeanBefore: a, scenarioMeanAfter: b, scenarioWeightBefore: wBefore, scenarioWeightAfter: wAfter };
  p(`No confirmation in bank 1.3 names more than one scenario, so the question does not arise in today's data; it would with a future bank or a bank change. Synthetic test on P3 (extended): ${target.id} (value ${fmt((target.value.lo + target.value.hi) / 2)}) is also made a confirmation of ${other.id} (whose own confirmations average ${fmt(meanOf(other.id))}). Option A reads each control once from its own row: ${fmt(s.overall.point)} before, ${fmt(s2.overall.point)} after the association is added to the report. An aggregation through scenarios (each scenario the mean of its confirmations, the result the mean of scenarios) moves from ${fmt(a)} to ${fmt(b)}, and the control's effective weight rises from ${(wBefore * 100).toFixed(2)}% to ${(wAfter * 100).toFixed(2)}% of the result (Option A pooled: ${((1 / scored.length) * 100).toFixed(2)}% for every scored control). check.mjs pins the invariance.`);
}

// ================================================================================================ 8. bands
h(2, '8. Maturity-band implications');
{
  const rows = [];
  const all = [...Object.entries(RUNS).map(([k, e]) => [k, e]), ...Object.entries(FIX).map(([k, f]) => [`fixture ${k}`, f.engine])];
  const tally = { capLowered: 0, indeterminate: 0, shown: 0, total: 0, mfrsProvisionalOrWorse: 0, proposedNormal: 0 };
  for (const [k, e] of all) {
    const rep = e.report();
    const s = simulate(rep), s1 = simulate(rep, { frame: 'A1' }), sm = simulate(rep, { visibility: 'mfrsComparator' });
    tally.total++; if (!s.overall.withheld) tally.shown++; if (s.band.capLowered) tally.capLowered++; if (s.band.indeterminate && !s.overall.withheld) tally.indeterminate++; if (sm.visibility.status !== 'NORMAL') tally.mfrsProvisionalOrWorse++; if (s.visibility.status === 'NORMAL') tally.proposedNormal++;
    rows.push([k, fmt(s.overall.point), s.band.calculated ? `${bandOf(s.overall.lo)}${s.band.indeterminate ? ` to ${bandOf(s.overall.hi)}` : ''}` : 'n/a', s.band.caps.join(', ') || 'none', s.overall.withheld ? 'withheld' : s.band.final, s1.overall.withheld ? 'withheld' : `${s1.band.final} (${fmt(s1.overall.point)})`, s.visibility.status, sm.visibility.status]);
  }
  results.bands = tally;
  table(['Record', 'Calculated', 'Band of the interval', 'Caps that bind', 'Final band, frame A', 'Final band, frame A1', 'Visibility (proposed)', 'Visibility (MFRS rules)'], rows);
  p(`Across ${tally.total} records: a band is shown for ${tally.shown}; caps lower the band for ${tally.capLowered}; the interval spans two bands for ${tally.indeterminate} of those shown; the MFRS visibility rules make ${tally.mfrsProvisionalOrWorse} of ${tally.total} provisional or insufficient (every exclusion counts), against ${tally.total - tally.proposedNormal} under the proposed rules.`);
  h(3, '8.1 Frame A1, pooled: cap variants and domain results');
  p('Frame A1 with every tier 1 confirmation weighted once (pooled). Caps: none; K1 to K3 (control-level caps on tier 1 confirmations); all (K1 to K4, K4 being a domain-level cap transposed from the MFRS core-domain caps although the revised method designates no core domains).');
  const capRows = [];
  const capTally = { none: {}, 'K1-K3': {}, all: {} };
  for (const [k, e] of all) {
    const rep = e.report();
    const v = ['none', 'K1-K3', 'all'].map((c) => [c, simulate(rep, { frame: 'A1', aggregation: 'pooled', caps: c })]);
    const s = v[0][1];
    for (const [c, x] of v) { const f = x.overall.withheld ? 'withheld' : x.band.final; capTally[c][f] = (capTally[c][f] || 0) + 1; }
    capRows.push([k, s.overall.withheld ? `withheld (${fmt(s.overall.point)})` : `${fmt(s.overall.point)} (${range(s.overall)})`, s.visibility.status, ...v.map(([, x]) => (x.overall.withheld ? 'withheld' : `${x.band.final}${x.band.capLowered ? ` (${x.band.caps.join(', ')})` : ''}`)), s.domains.filter((d) => d.scored >= 3).length, s.domains.filter((d) => d.scored > 0 && d.scored < 3).map((d) => `${d.id} (${d.scored})`).join(', ') || 'none']);
  }
  results.bandsA1 = capTally;
  table(['Record', 'Frame A1 pooled result', 'Visibility', 'Band, no caps', 'Band, K1 to K3', 'Band, all caps', 'Domains with 3 or more scored tier 1 confirmations', 'Domains with only 1 or 2'], capRows);
}

// ================================================================================================ 9. recommended configuration
h(2, '9. The recommended configuration, tested');
p(`Every element below is the recommendation in METHODOLOGY-DECISION-PACKAGE.md, still hypothetical: frame A1; class answers by the method-derived interval, the published figure its midpoint; every tier 1 confirmation weighted once (pooled); F2 with F4 and disclosure; caps K1 to K3; the recommended visibility rule; the band from the lower end of the range.`);
results.recommended = { params: RECOMMENDED, records: {} };
{
  h(3, '9.1 Every record');
  const rows = [];
  const all = [...Object.entries(RUNS), ...Object.entries(FIX).map(([k, f]) => [`fixture ${k}`, f.engine])];
  for (const [k, e] of all) {
    const s = simulate(e.report(), RECOMMENDED);
    results.recommended.records[k] = brief(s);
    rows.push([k, `${s.population.known} / ${s.population.applicable}${s.population.pendingApplicability ? ` (+${s.population.pendingApplicability} not known)` : ''}`, `${fmt(s.metrics.outstandingSharePct)}%`, s.visibility.status, s.overall.withheld ? `withheld (${fmt(s.overall.point)})` : `${fmt(s.overall.point)} (${range(s.overall)})`, s.overall.withheld ? 'withheld' : `${s.band.final}${s.band.capLowered ? ` (from ${s.band.calculated}: ${s.band.caps.join(', ')})` : ''}`, s.domains.filter((d) => d.visible).length, s.contradictions.filter((c) => c.kind.startsWith('in-place')).length]);
  }
  table(['Record', 'Known / applicable tier 1', 'Outstanding', 'Visibility', 'Result', 'Band', 'Domain figures shown', 'Contradicted confirmations (F2 applied)'], rows);
}
{
  h(3, '9.2 How far an incomplete record can move the result');
  p('Thirty seeds per rate, production limit, answers replaced at random by "I don\'t know". Deviation is from the same organisation with every answer given. "Band differs" counts the runs whose band (lower end) differs from the complete band.');
  const rows = [];
  results.recommended.deviation = [];
  for (const pol of ['mixed', 'uniform', 'strong', 'weak']) {
    const complete = simulate(interview({ profile: 'R', policy: POLICIES[pol], ceiling: PRODUCTION_CEILING }).report(), { ...RECOMMENDED });
    for (const rate of [0.05, 0.1, 0.15, 0.2]) {
      const runs = [];
      for (let k = 0; k < 30; k++) runs.push(simulate(interview({ profile: 'R', policy: withUnknown(POLICIES[pol], rate, `dev-${k}`), ceiling: PRODUCTION_CEILING }).report(), RECOMMENDED));
      const d = runs.map((s) => s.overall.point - complete.overall.point).sort((x, y) => x - y);
      const st = runs.reduce((a, s) => ((a[s.visibility.status] = (a[s.visibility.status] || 0) + 1), a), {});
      const shownRuns = runs.filter((s) => !s.overall.withheld);
      const bandDiff = runs.filter((s) => bandOf(s.overall.lo) !== bandOf(complete.overall.lo)).length;
      const bandDiffShown = shownRuns.filter((s) => s.band.final !== complete.band.final).length;
      const dShown = shownRuns.map((s) => Math.abs(s.overall.point - complete.overall.point));
      results.recommended.deviation.push({ pattern: pol, rate, complete: complete.overall.point, p5: d[1], p95: d[28], maxAbs: Math.max(...d.map(Math.abs)), status: st, bandDiff, bandDiffShown, shown: shownRuns.length, maxAbsShown: dShown.length ? Math.max(...dShown) : null });
      rows.push([pol, `${Math.round(rate * 100)}%`, fmt(complete.overall.point), `${fmt(d[1])} to +${fmt(Math.max(0, d[28]))}`, fmt(Math.max(...d.map(Math.abs))), Object.entries(st).map(([a, n]) => `${a} ${n}`).join(', '), `${bandDiff} of 30`, shownRuns.length ? `${fmt(Math.max(...dShown))} / ${bandDiffShown} of ${shownRuns.length}` : 'none shown']);
    }
  }
  table(['Answer pattern', 'Unknown rate', 'Complete result', 'Deviation (5th to 95th percentile)', 'Largest deviation', 'Visibility (of 30)', 'Band differs (calculated)', 'Shown runs: largest deviation / band differs'], rows);
}
{
  h(3, '9.3 The respondent stops early');
  const rows = [];
  for (const pol of ['strong', 'mixed', 'weak']) {
    const complete = simulate(interview({ profile: 'R', policy: POLICIES[pol], ceiling: PRODUCTION_CEILING }).report(), RECOMMENDED);
    for (const stop of [40, 60, 70, 80, 90]) {
      const s = simulate(interview({ profile: 'R', policy: POLICIES[pol], ceiling: PRODUCTION_CEILING, stopAfter: stop }).report(), RECOMMENDED);
      rows.push([pol, stop, `${fmt(s.metrics.outstandingSharePct)}%`, s.visibility.status, `${fmt(s.overall.point)} (complete ${fmt(complete.overall.point)})`, s.overall.withheld ? 'withheld' : s.band.final]);
    }
  }
  table(['Answer pattern', 'Respondent stops after', 'Outstanding', 'Visibility', 'Calculated result', 'Band shown'], rows);
}
{
  h(3, '9.4 What each recommended element changes');
  p('Starting from the default simulation (frame A, equal domains, F0, all caps, the first proposed visibility rule, band from the point), each column adds one element of the recommendation. Values are the result shown, or "withheld", with the band.');
  const steps = [['Default (frame A)', {}], ['+ frame A1', { frame: 'A1' }], ['+ pooled', { frame: 'A1', aggregation: 'pooled' }], ['+ F2 and F4', { frame: 'A1', aggregation: 'pooled', falseComfort: 'F2F4' }], ['+ caps K1 to K3 only', { frame: 'A1', aggregation: 'pooled', falseComfort: 'F2F4', caps: 'K1-K3' }], ['+ recommended visibility', { frame: 'A1', aggregation: 'pooled', falseComfort: 'F2F4', caps: 'K1-K3', visibility: 'recommended' }], ['+ band from the lower end', RECOMMENDED]];
  const rows = [];
  for (const [k, e] of [['P3 mixed, production limit', RUNS[`P3@${PRODUCTION_CEILING}`]], ['P4 limited, production limit', RUNS[`P4@${PRODUCTION_CEILING}`]], ['P5 unknowns, production limit', RUNS[`P5@${PRODUCTION_CEILING}`]], ['P6 contradictions, production limit', RUNS[`P6@${PRODUCTION_CEILING}`]], ['P6 contradictions, extended', RUNS[`P6@${EXTENDED_CEILING}`]], ['Supplied fixture', FIX.supplied.engine], ['Golden routes', FIX.routes.engine]]) {
    const rep = e.report();
    rows.push([k, ...steps.map(([, o]) => { const s = simulate(rep, o); return s.overall.withheld ? `withheld (${s.visibility.status})` : `${fmt(s.overall.point)} ${s.band.final} (${s.visibility.status})`; })]);
  }
  table(['Record', ...steps.map(([k]) => k)], rows);
}

{
  h(3, '9.5 Owners answer the outstanding confirmations later');
  const e = interview({ profile: 'R', policy: withUnknown(POLICIES.mixed, 0.35), ceiling: PRODUCTION_CEILING });
  const before = simulate(e.report(), RECOMMENDED);
  let returned = 0;
  for (const id of FRAME_IDS) { const a = e.S.ans[id]; if (a && a.v === 'unknown') { e.ownerReturn(id, practiceValue(e.QI[id], POLICIES.mixed(QI.get(id), 'mk-sim')), { by: 'Fictional owner' }); returned++; } }
  const after = simulate(e.report(), RECOMMENDED);
  const complete = simulate(RUNS[`P3@${PRODUCTION_CEILING}`].report(), RECOMMENDED);
  results.recommended.ownersLater = { before: brief(before), after: brief(after), returned, complete: complete.overall };
  table(['Run', 'Outstanding', 'Visibility', 'Result', 'Band'], [
    ['P5 at the production limit (initial run)', `${fmt(before.metrics.outstandingSharePct)}%`, before.visibility.status, before.overall.withheld ? `withheld (${fmt(before.overall.point)})` : fmt(before.overall.point), before.band.final || 'withheld'],
    [`After owners answer ${returned} confirmations (a correction recalculation)`, `${fmt(after.metrics.outstandingSharePct)}%`, after.visibility.status, after.overall.withheld ? `withheld (${fmt(after.overall.point)})` : `${fmt(after.overall.point)} (${range(after.overall)})`, after.band.final || 'withheld'],
    ['The same organisation answering everything itself (P3)', `${fmt(complete.metrics.outstandingSharePct)}%`, complete.visibility.status, fmt(complete.overall.point), complete.band.final]
  ]);
}
{
  h(3, '9.6 Strategic use of "I don\'t know" under the recommended configuration');
  const e = RUNS[`P2@${PRODUCTION_CEILING}`];
  const rep = e.report();
  const base = simulate(rep, RECOMMENDED);
  const order = base.controls.filter((c) => c.category === 'known').sort((a, b) => a.value.lo + a.value.hi - (b.value.lo + b.value.hi));
  const rows = [];
  let lastShown = null;
  for (let k = 0; k <= Math.min(order.length, 12); k++) {
    const s = simulate(rep, { ...RECOMMENDED, overrides: Object.fromEntries(order.slice(0, k).map((c) => [c.id, 'unknown'])) });
    if (!s.overall.withheld) lastShown = { k, point: s.overall.point, status: s.visibility.status };
    rows.push([k, `${fmt(s.metrics.outstandingSharePct)}%`, fmt(s.overall.point), s.visibility.status, s.overall.withheld ? 'withheld' : s.band.final]);
  }
  results.recommended.strategicUnknown = { base: base.overall.point, lastShown };
  p(`P2 weak at the production limit, the lowest tier 1 answers withheld one at a time. Base ${fmt(base.overall.point)} (${base.visibility.status}). The last result shown is after ${lastShown.k} answers withheld: ${fmt(lastShown.point)}, ${lastShown.status}, with every withheld confirmation listed as outstanding.`);
  table(['Answers withheld', 'Outstanding', 'Calculated result', 'Visibility', 'Band shown'], rows);
}

writeFileSync(path.join(OUT, 'results.json'), `${JSON.stringify(results, null, 1)}\n`);
writeFileSync(path.join(OUT, 'SIMULATION-RESULTS.md'), `${md.join('\n').replace(/\n{3,}/g, '\n\n')}\n`);
console.log(`wrote ${path.relative(ROOT, OUT)}: membership-matrix.csv (${mrows.length} rows), membership-summary.json, results.json, SIMULATION-RESULTS.md`);
